// === Tab: mySketch.js ===
let palette = ['#000000', '#ff0000'];
let vmin, vmax;
let glsl;
let col1, col2;

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1376452/files/shader.vert', 'shader.frag');
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  smooth();
  noStroke();
  vmin = (width < height) ? width : height;
  vmax = (width > height) ? width : height;
  col1 = color(palette[1]);
	perspective(60 / 180 * PI, width / height, 0.1, vmax * 5);
}

function draw() {
  let sec = millis() / 1000;

  background(palette[0]);

  shader(glsl);
  glsl.setUniform('uTime', sec * 0.05);
  glsl.setUniform('uColor', col1._array);
  glsl.setUniform('uLineWidth', 0.1);
  glsl.setUniform('uDepth', vmax * 3.5);
  push();
  {
    rotateX(sec * -0.05);
    rotateY(sec * 0.1);
    // rotateZ(sec * 0.15);
    scale(vmax * 2.5);
    box(1);
  }
  pop();

  glsl.setUniform('uTime', -sec * 0.025);
  glsl.setUniform('uColor', col1._array);
  glsl.setUniform('uLineWidth', 0.4);
  glsl.setUniform('uDepth', vmax * 3.5);
  push();
  {
    rotateX(sec * 0.15);
    rotateY(sec * -0.1);
    // rotateZ(sec * -0.05);
    scale(vmax * 2.5);
    box(1);
  }
  pop();

  blendMode(BLEND);
}

// === Tab: shader.vert ===
attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

varying vec2 vTexCoord;
varying vec4 vPos;

void main() {
  vTexCoord = aTexCoord;
  vec4 position = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * position;
  vPos = gl_Position;
}

// === Tab: shader.frag ===
precision mediump float;

uniform float uTime;
uniform vec3 uColor;
uniform float uLineWidth;
uniform float uDepth;

varying vec2 vTexCoord;
varying vec4 vPos;

void main() {
  vec2 uv = vTexCoord;

  float l = dot(uv + uTime, vec2(1., 1.));
  float m = uLineWidth;
  l = mod(l, m) * (1. / m);
  l = step(l, .5);
  if (l < 1.0) {
    discard;
  }

  float d = 1.55 - vPos.z / (uDepth / sqrt(2.));
  d = d * d * d;

  gl_FragColor = vec4(uColor - d, 1.0);
}

